#!/usr/bin/env bash
# ⑤ 3차 추가 실측 — H1~H7 · N1~N10 · m 항목 전용 (dyn2.sh 뒤에 실행)
B="$HOME/.claude/skills/gstack/browse/dist/browse"
W="C:/Projects/Active/교대근무관리 시스템/시안/2026-09-02-2차HTML"
J() { "$B" js "$1" 2>/dev/null | grep -v "BEGIN\|END" | grep -v '^\s*$'; }
G() { "$B" goto "file:///$W/$1" >/dev/null 2>&1; "$B" wait --load >/dev/null 2>&1; }
P() { "$B" press "$1" >/dev/null 2>&1; }
SHELL_STATES() {
J "(()=>{const out=[];for(const w of document.querySelectorAll('.state-wrapper')){const foot=w.querySelector('.footer-statusbar');let cells=[];if(foot){let c=[...foot.querySelectorAll('[class*=cell],[class*=item]')].filter(e=>e.parentElement===foot||e.parentElement.parentElement===foot);if(!c.length)c=[...foot.children];cells=c.map(x=>x.innerText.replace(/\s+/g,' ').trim()+(x.title?'{title:'+x.title+'}':'')+' bg='+getComputedStyle(x).backgroundColor);}const desc=[...w.querySelectorAll('*')].filter(e=>e.children.length===0&&/\(S[1-6]\)/.test(e.textContent)).length;const skel=[...w.querySelectorAll('[class*=skeleton]')];const skelHidden=skel.filter(e=>e.closest('[aria-hidden=true]')).length;const band=[...w.querySelectorAll('[class*=band],[class*=banner],[class*=alert],[class*=notice],[class*=warn],[role=alert],[role=status]')].filter(e=>e.offsetParent!==null&&e.children.length<12).map(e=>e.innerText.replace(/\s+/g,' ').trim().slice(0,140)+' btns='+[...e.querySelectorAll('button')].map(b=>b.textContent.trim()||b.getAttribute('aria-label')).join('|'));const hdrUser=(w.querySelector('.header-user,[class*=user]')||{innerText:'?'}).innerText.replace(/\s+/g,' ').trim().slice(0,40);out.push(w.id+' cells('+cells.length+'): '+cells.join(' │ ')+'\n   descCards='+desc+' skeleton='+skel.length+'(ariaHidden '+skelHidden+') hdrUser='+hdrUser+'\n   band: '+band.join(' ## '));}return out.join('\n');})()"
}
echo "=============== H1 00-shell-1 S1~S3 ==============="
G 00-shell-1.html; SHELL_STATES
echo "=============== H1 00-shell-2 S4~S6 ==============="
G 00-shell-2.html; SHELL_STATES
echo "-- H2 S6 상세 모달 전문"
J "(()=>{document.getElementById('btn-open-s6-banner').click();const m=document.getElementById('modal-s6-update');const box=m.querySelector('.modal-box');const badges=[...m.querySelectorAll('[class*=badge],[class*=pill],[class*=chip]')].map(e=>e.textContent.trim()+'('+getComputedStyle(e).backgroundColor+')');return 'boxW='+Math.round(box.getBoundingClientRect().width)+' title='+m.querySelector('.modal-title').textContent.trim()+' | badges='+badges.join(',')+' | ol/li='+m.querySelectorAll('ol li').length+' | btns='+[...m.querySelectorAll('button')].map(b=>(b.textContent.trim()||b.getAttribute('aria-label'))+'['+b.className.split(' ').filter(c=>/btn-/.test(c)).join(',')+']').join('|')+'\n   본문: '+m.innerText.replace(/\s+/g,' ').trim().slice(0,700);})()"
P Escape
echo "-- N1 S6: 열림 중 배경 aria-hidden 범위"
J "(()=>{const w=document.getElementById('state-s6');const m=document.getElementById('modal-s6-update');const cnt=()=>[...w.querySelectorAll('[aria-hidden=true]')].filter(e=>!m.contains(e)&&!e.closest('[class*=skeleton]')&&!e.classList.contains('material-symbols-outlined')).map(e=>e.tagName.toLowerCase()+'.'+(e.className||'').toString().split(' ')[0]);const b=cnt();document.getElementById('btn-open-s6-banner').click();const a=cnt();const inside=!!m.closest('[aria-hidden=true]');const sib=m.parentElement===w;const x=m.querySelector('.btn-modal-close-x,[aria-label*=닫기]');if(x)x.click();const c=cnt();return 'before='+JSON.stringify(b)+' open='+JSON.stringify(a)+' modalInsideHidden='+inside+' modalIsWrapperChild='+sib+' after='+JSON.stringify(c);})()"

echo "=============== H4~H7 02-common-1/2/3 ==============="
for f in 02-common-1 02-common-2 02-common-3; do
G "$f.html"; echo "-- $f"
J "(()=>{const shell=document.querySelectorAll('.sidebar,.header-bar,.footer-statusbar,.app-body>nav').length;const caps=[...document.querySelectorAll('.demo-caption,[class*=caption]')].map(e=>'['+e.textContent.replace(/\s+/g,' ').trim().slice(0,60)+']'+getComputedStyle(e).fontSize+(e.offsetParent!==null?'':'(숨김)'));const h2=[...document.querySelectorAll('h1,h2,h3')].map(e=>e.textContent.trim()).filter(t=>/데모/.test(t));const stage=[...document.querySelectorAll('.state-wrapper')].map(w=>{const aw=w.querySelector('.app-window,[class*=stage],[class*=frame]');return w.id+':'+(aw?Math.round(aw.getBoundingClientRect().width)+'x'+Math.round(aw.getBoundingClientRect().height)+' bg='+getComputedStyle(aw).backgroundColor:'noframe');});return 'shell부품='+shell+' | captions('+caps.length+')='+caps.join(' ; ')+' | 데모 제목='+h2.join(',')+' | frames='+stage.join(' ');})()"
done
G 02-common-1.html
J "(()=>{return [1,2,3,4].map(i=>{const t=document.getElementById('btn-open-c'+i);t.click();const m=document.getElementById('modal-c'+i);const box=m.querySelector('.modal-box');const r='C'+i+' boxW='+Math.round(box.getBoundingClientRect().width)+' title='+(m.querySelector('.modal-title')||{textContent:'?'}).textContent.trim()+' btns='+[...m.querySelectorAll('button')].map(b=>b.textContent.trim()||b.getAttribute('aria-label')).join('|')+' 본문='+m.innerText.replace(/\s+/g,' ').trim().slice(0,150);const x=m.querySelector('.btn-modal-close-x,[aria-label*=닫기]');if(x)x.click();return r;}).join('\n');})()"
J "(()=>{document.getElementById('btn-open-c3').click();const m=document.getElementById('modal-c3');const del=[...m.querySelectorAll('button')].find(b=>b.textContent.trim()==='삭제');return 'C3 [삭제] bg='+getComputedStyle(del).backgroundColor+' color='+getComputedStyle(del).color;})()"
P Escape
G 02-common-2.html
J "(()=>{const w=document.getElementById('state-c9');const bs=[...w.querySelectorAll('button')].map(b=>b.textContent.trim()+(b.getAttribute('aria-disabled')==='true'?'[a-dis desc='+(document.getElementById(b.getAttribute('aria-describedby')||'')||{textContent:'없음'}).textContent.trim()+']':'')+(b.disabled?'[disabled]':''));const toasts=[...document.querySelectorAll('[class*=toast]')].filter(e=>e.children.length<8).map(e=>e.innerText.replace(/\s+/g,' ').trim().slice(0,90)+' pos='+getComputedStyle(e).position+'/'+getComputedStyle(e).right+'/'+getComputedStyle(e).bottom+' x='+!!e.querySelector('[aria-label*=닫기],.btn-toast-close,button'));const c8=document.getElementById('state-c8').innerText.replace(/\s+/g,' ').trim().slice(0,160);return 'C9 btns='+bs.join(' | ')+'\n   toasts='+toasts.join(' ## ')+'\n   C8='+c8;})()"
G 02-common-3.html
J "(()=>{const c10=document.getElementById('state-c10');const rows=c10.querySelectorAll('table tbody tr,[class*=skeleton-row],[class*=skel-row]').length;const cards=c10.querySelectorAll('[class*=card]').length;const c11=document.getElementById('state-c11');const bars=[...c11.querySelectorAll('[class*=track],[class*=bar],[class*=progress]')].map(e=>e.className.split(' ')[0]+':'+Math.round(e.getBoundingClientRect().height)+'px');const c12=document.getElementById('state-c12');const sp=[...c12.querySelectorAll('*')].filter(e=>getComputedStyle(e).animationName!=='none').map(e=>e.className.split(' ')[0]+':'+getComputedStyle(e).animationName);return 'C10 rows='+rows+' cards='+cards+' skeletonEls='+c10.querySelectorAll('[class*=skeleton]').length+' | C11 bars='+bars.join(',')+' text='+c11.innerText.replace(/\s+/g,' ').trim().slice(0,120)+' | C12 anim='+sp.join(',')+' text='+c12.innerText.replace(/\s+/g,' ').trim().slice(0,80);})()"

echo "=============== N6 데모 캡션 · N1 배경 범위 (모달 파일) ==============="
for pair in "04-sites-1.html btn-open-t2 modal-t2 state-t2" "04-sites-2.html btn-open-t4 modal-t4 state-t4" "06-employees-2.html btn-open-e3 modal-e3 state-e3" "06-employees-2.html btn-open-e4 modal-e4 state-e4" "06-employees-3.html btn-open-e6 modal-e6 state-e6" "07-schedule-3.html btn-open-r4 modal-r4 state-r4" "09-allowance-2.html btn-open-a3 modal-a3 state-a3" "09-allowance-2.html btn-open-a4 modal-a4 state-a4" "11-operations-4.html btn-open-o9 modal-o9 state-o9"; do
  set -- $pair; G "$1"; echo -n "$1 $4: "
  J "(()=>{const m=document.getElementById('$3');const w=document.getElementById('$4')||m.closest('.state-wrapper');const t=document.getElementById('$2');const cap=[...w.querySelectorAll('.demo-caption,[class*=caption]')].filter(e=>/데모용/.test(e.textContent)).map(e=>'['+e.textContent.replace(/\s+/g,' ').trim()+']'+getComputedStyle(e).fontSize);const h2=[...w.querySelectorAll('h1,h2,h3')].map(e=>e.textContent.trim()).filter(x=>/데모/.test(x));const cnt=()=>[...w.querySelectorAll('[aria-hidden=true]')].filter(e=>!m.contains(e)&&!e.classList.contains('material-symbols-outlined')&&!e.closest('[class*=skeleton]')).map(e=>e.tagName.toLowerCase()+'.'+(e.className||'').toString().split(' ')[0]);const b=cnt();t.click();const a=cnt();const inside=!!m.closest('[aria-hidden=true]');const boxW=Math.round(m.querySelector('.modal-box').getBoundingClientRect().width);const x=m.querySelector('.btn-modal-close-x,[aria-label*=닫기]')||[...m.querySelectorAll('button')].find(q=>/취소|닫기|나중에/.test(q.textContent));if(x)x.click();const c=cnt();return 'caption='+cap.join(';')+' 데모제목='+h2.join(',')+' | boxW='+boxW+' insideHidden='+inside+' bg before='+b.length+' open='+JSON.stringify(a)+' after='+c.length+' trigger='+t.textContent.trim();})()"
done
echo "-- A5·O10 (연쇄 2단계) 폭·배경"
G 09-allowance-2.html
J "(()=>{document.getElementById('btn-open-a3').click();document.getElementById('btn-goto-a5').click();const m=document.getElementById('modal-a5');return 'A5 boxW='+Math.round(m.querySelector('.modal-box').getBoundingClientRect().width)+' insideHidden='+!!m.closest('[aria-hidden=true]')+' 본문='+m.innerText.replace(/\s+/g,' ').trim().slice(0,200);})()"
G 11-operations-4.html
J "(()=>{document.getElementById('btn-open-o9').click();document.getElementById('btn-goto-o10').click();const m=document.getElementById('modal-o10');return 'O10 boxW='+Math.round(m.querySelector('.modal-box').getBoundingClientRect().width)+' insideHidden='+!!m.closest('[aria-hidden=true]');})()"

echo "=============== N5 12-access-logs-1 G1·G2 ==============="
G 12-access-logs-1.html
J "(()=>{const w=document.getElementById('state-g1');const t=w.querySelector('table');const th=[...t.querySelectorAll('thead th')].map(x=>x.textContent.trim());const rows=[...t.tBodies[0].rows].map(r=>[...r.cells].map(c=>c.innerText.replace(/\s+/g,' ').trim()).join(' / '));const sels=[...w.querySelectorAll('select')].map(s=>(s.id||s.getAttribute('aria-label')||'')+'['+[...s.options].map(o=>o.textContent.trim()).join(',')+']');const ph=[...w.querySelectorAll('input[placeholder]')].map(i=>i.placeholder);const sub=(w.querySelector('.page-subtitle,[class*=subtitle],[class*=desc]')||{textContent:'?'}).textContent.trim();const badges=[...t.querySelectorAll('tbody [class*=badge],tbody [class*=pill],tbody [class*=chip]')].map(e=>e.textContent.trim()+'('+getComputedStyle(e).backgroundColor+')');return 'th='+th.join('|')+'\n   rows('+rows.length+'):\n   '+rows.join('\n   ')+'\n   selects='+sels.join(' ; ')+'\n   placeholder='+ph.join(',')+'\n   부제='+sub+'\n   badges='+[...new Set(badges)].join(',')+'\n   G1 buttons='+[...w.querySelectorAll('button')].map(b=>b.textContent.trim()).join(',')+' | G2 buttons='+[...document.querySelectorAll('#state-g2 button')].map(b=>b.textContent.trim()).join(',')+' G2 text='+document.getElementById('state-g2').innerText.replace(/\s+/g,' ').trim().slice(-160);})()"

echo "=============== N3·N4 11-operations-1 O1·O2 / -2 O3 / -3 O8 ==============="
G 11-operations-1.html
J "(()=>{const w=document.getElementById('state-o1');const labels=[...w.querySelectorAll('label,[class*=label]')].map(e=>e.textContent.replace(/\s+/g,' ').trim()).filter(t=>t&&t.length<30);const cards=[...w.querySelectorAll('[class*=card-title],[class*=card] h2,[class*=card] h3,[class*=card] h4')].map(e=>e.textContent.trim());const btns=[...w.querySelectorAll('button')].map(b=>b.textContent.trim());const ro=[...w.querySelectorAll('input[readonly]')].map(i=>(i.id||'')+'='+i.value.slice(0,40));const ph=[...w.querySelectorAll('input[placeholder]')].map(i=>i.placeholder);return 'O1 labels='+labels.join('|')+'\n   cards='+cards.join('|')+'\n   btns='+btns.join(',')+'\n   readonly='+ro.join(' ; ')+'\n   placeholders='+ph.join(' ; ')+'\n   2026-07-01='+/2026-07-01/.test(w.innerText);})()"
J "(()=>{const w=document.getElementById('state-o2');const cards=[...w.querySelectorAll('[class*=card-title],[class*=card] h2,[class*=card] h3,[class*=card] h4')].map(e=>e.textContent.trim());const cal=w.querySelectorAll('[class*=calendar],[class*=mini-cal],[class*=month]').length;const months=[...w.querySelectorAll('*')].filter(e=>e.children.length===0&&/^2025년 [1-6]월$|^[1-6]월$/.test(e.textContent.trim())).map(e=>e.textContent.trim());const hol=[...w.querySelectorAll('[class*=holiday],[class*=cal] [class*=hol],td[class*=hol]')].length;return 'O2 cards='+cards.join('|')+' | calendars='+cal+' months='+months.join(',')+' holidayCells='+hol+' | btns='+[...w.querySelectorAll('button')].map(b=>b.textContent.trim()).filter((v,i,a)=>a.indexOf(v)===i).join(',')+' | 캡션='+/1~6월 표시 · 하반기는 스크롤/.test(w.innerText)+' | 설명='+/현재 저장 목록과 API 원본을 같은 연도로 비교합니다\./.test(w.innerText);})()"
G 11-operations-2.html
J "(()=>{const w=document.getElementById('state-o3');const sels=[...w.querySelectorAll('select')].map(s=>'['+[...s.options].map(o=>o.textContent.trim()).join('/')+']');const inputs=[...w.querySelectorAll('input:not([type=number]),textarea')].map(i=>(i.id||i.name||'')+':'+(i.placeholder||i.value||'').slice(0,30));const labels=[...w.querySelectorAll('label')].map(l=>l.textContent.trim());const card=[...w.querySelectorAll('[class*=card]')].find(e=>/요율 영향 미리보기/.test(e.textContent)&&e.textContent.length<600);return 'O3 selects='+sels.join(' ')+' | labels='+labels.join('|')+' | inputs='+inputs.join(' ; ')+'\n   영향카드='+(card?card.innerText.replace(/\s+/g,' ').trim().slice(0,260):'없음');})()"
G 11-operations-3.html
J "(()=>{const w=document.getElementById('state-o8');const th=[...w.querySelectorAll('table thead th')].map(x=>x.textContent.trim());const cards=[...w.querySelectorAll('[class*=card],[class*=kpi],[class*=summary]')].filter(e=>e.children.length<=4&&e.textContent.trim().length<30).map(e=>e.innerText.replace(/\s+/g,' ').trim());return 'O8 th='+th.join('|')+' | cards='+[...new Set(cards)].join(' ; ');})()"

echo "=============== 잔여 문구 확인(2차 phrases 없음 4건) ==============="
G 01-login-1.html
J "(()=>{const e=[...document.querySelectorAll('#state-l3 *')].filter(x=>x.children.length<=2&&/잠겼/.test(x.textContent)).map(x=>x.innerText.replace(/\s+/g,' ').trim().slice(0,120));return 'L3 잠김 문구: '+e.join(' / ');})()"
G 06-employees-1.html
J "(()=>{const e=[...document.querySelectorAll('#state-e2 *')].filter(x=>x.children.length<=2&&/A조/.test(x.textContent)).slice(0,2).map(x=>x.innerText.replace(/\s+/g,' ').trim().slice(0,60));return 'E2 배정 이력: '+e.join(' / ');})()"
G 07-schedule-1.html
J "(()=>{const e=[...document.querySelectorAll('*')].filter(x=>x.children.length===0&&/4조 ?3교대/.test(x.textContent)).map(x=>x.textContent.trim());return 'R1 패턴명: '+[...new Set(e)].join(' / ');})()"
G 09-allowance-1.html
J "(()=>{const e=[...document.querySelectorAll('#state-a1 *')].filter(x=>x.children.length<=1&&/19\.0/.test(x.textContent)&&x.textContent.trim().length<20).map(x=>x.innerText.replace(/\s+/g,' ').trim());return 'A1 시간 카드: '+e.join(' / ');})()"
echo DONE
